// kit v1 backend example ("widget"): Hono routes, env.db for data, x-app-user
// for identity. See ../README.md for the three-dependency contract.
import { Hono } from "hono";

interface Env {
  db: {
    execute: (sql: string, params?: unknown[]) => { rows: Record<string, unknown>[]; columns: string[]; rowsAffected: number };
    batch: (stmts: { sql: string; params?: unknown[] }[]) => unknown[];
  };
}

function currentUser(request: Request): { id: string; name: string; email: string } | null {
  const raw = request.headers.get("x-app-user");
  if (!raw) return null;
  try {
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

const app = new Hono<{ Bindings: Env }>();

// Non-GET / non-static paths that aren't index.html fall through here (the
// hub serves dist/index.html and dist/assets/* directly as static files).
app.get("/api/items", (c) => {
  const { rows } = c.env.db.execute("SELECT id, label, created_at FROM items ORDER BY id DESC");
  return c.json({ items: rows });
});

app.post("/api/items", async (c) => {
  const body = await c.req.json<{ label?: string }>();
  if (!body.label) return c.json({ error: "label is required" }, 400);
  c.env.db.execute("INSERT INTO items (label, created_at) VALUES (?, ?)", [body.label, Date.now()]);
  return c.json({ ok: true });
});

// Tool route (see ../tools.json): callable by the colleague, same request
// shape as any other route -- identity arrives the same way.
app.post("/api/tools/count_items", (c) => {
  const { rows } = c.env.db.execute("SELECT COUNT(*) AS n FROM items");
  const user = currentUser(c.req.raw);
  return c.json({ count: rows[0]?.n ?? 0, calledBy: user?.name ?? null });
});

export default {
  fetch: (request: Request, env: Env) => app.fetch(request, env),
};

import http from 'node:http';
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const publicDir = join(here, 'public');
const dataDir = process.env.DATA_DIR || join(here, 'data');
const dataFile = join(dataDir, 'entries.json');
const port = Number(process.env.PORT || 3000);
let writeQueue = Promise.resolve();

async function entries() {
  try {
    const value = JSON.parse(await readFile(dataFile, 'utf8'));
    return Array.isArray(value) ? value : [];
  } catch (error) {
    if (error.code === 'ENOENT') return [];
    throw error;
  }
}

function save(value) {
  writeQueue = writeQueue.then(async () => {
    await mkdir(dataDir, { recursive: true });
    const temporary = `${dataFile}.${process.pid}.tmp`;
    await writeFile(temporary, JSON.stringify(value, null, 2));
    await rename(temporary, dataFile);
  });
  return writeQueue;
}

function send(response, status, body, type = 'application/json; charset=utf-8', headers = {}) {
  response.writeHead(status, { 'content-type': type, 'cache-control': 'no-store', ...headers });
  response.end(type.startsWith('application/json') ? JSON.stringify(body) : body);
}

async function body(request) {
  let raw = '';
  for await (const chunk of request) {
    raw += chunk;
    if (raw.length > 32_768) throw Object.assign(new Error('Request too large'), { status: 413 });
  }
  const type = request.headers['content-type'] || '';
  if (type.includes('application/json')) return JSON.parse(raw || '{}');
  return Object.fromEntries(new URLSearchParams(raw));
}

function clean(value, max) {
  return String(value || '').trim().replace(/[\u0000-\u001f]/g, '').slice(0, max);
}

const server = http.createServer(async (request, response) => {
  try {
    const url = new URL(request.url, 'http://guestbook.local');
    if (request.method === 'GET' && url.pathname === '/') {
      return send(response, 200, await readFile(join(publicDir, 'index.html'), 'utf8'), 'text/html; charset=utf-8');
    }
    if (request.method === 'GET' && url.pathname === '/api/entries') {
      return send(response, 200, { entries: (await entries()).slice().reverse() });
    }
    if (request.method === 'POST' && url.pathname === '/api/entries') {
      const input = await body(request);
      const name = clean(input.name, 60);
      const message = clean(input.message, 500);
      if (!name || !message) return send(response, 400, { error: 'Name and message are required.' });
      const all = await entries();
      const entry = { id: crypto.randomUUID(), name, message, createdAt: new Date().toISOString() };
      all.push(entry);
      await save(all);
      return send(response, 201, { entry }, undefined, { location: `/api/entries/${entry.id}` });
    }
    if (request.method === 'GET' && url.pathname === '/tools') {
      return send(response, 200, { tools: [{ name: 'count_entries', description: 'Count entries currently stored in the guestbook.', inputSchema: { type: 'object', properties: {}, additionalProperties: false } }] });
    }
    if (request.method === 'POST' && (url.pathname === '/tools/count_entries' || url.pathname === '/api/tools/count_entries')) {
      const count = (await entries()).length;
      return send(response, 200, { count, content: [{ type: 'text', text: String(count) }] });
    }
    if (request.method === 'GET' && url.pathname === '/healthz') return send(response, 200, { ok: true });
    send(response, 404, { error: 'Not found' });
  } catch (error) {
    console.error(error);
    send(response, error.status || 500, { error: error.status ? error.message : 'Internal server error' });
  }
});

server.listen(port, '0.0.0.0', () => console.log(`Guestbook listening on ${port}`));

