import { createRootRoute, createRoute, createRouter, Outlet } from "@tanstack/react-router";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";

// The hub always serves dist/index.html for the app's root path (GET / with
// no rest), so at initial load location.pathname IS the app's mount point.
// Derive the router basepath from it so the same build works under any
// /w/{workspaceId}/{name}/ path.
export const basepath = window.location.pathname.endsWith("/")
  ? window.location.pathname
  : window.location.pathname.replace(/\/[^/]*$/, "/");

interface Item {
  id: number;
  label: string;
  created_at: number;
}

function Widget() {
  const qc = useQueryClient();
  const itemsQuery = useQuery({
    queryKey: ["items"],
    queryFn: async (): Promise<Item[]> => {
      const res = await fetch("api/items");
      const body = await res.json();
      return body.items ?? [];
    },
  });
  const addItem = useMutation({
    mutationFn: async (label: string) => {
      await fetch("api/items", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ label }) });
    },
    onSuccess: () => qc.invalidateQueries({ queryKey: ["items"] }),
  });

  return (
    <main style={{ fontFamily: "system-ui, sans-serif", maxWidth: 480, margin: "2rem auto" }}>
      <h1>kit widget</h1>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          const form = e.currentTarget;
          const input = form.elements.namedItem("label") as HTMLInputElement;
          if (input.value.trim()) addItem.mutate(input.value.trim());
          form.reset();
        }}
      >
        <input name="label" placeholder="new item" />
        <button type="submit">Add</button>
      </form>
      <ul>
        {(itemsQuery.data ?? []).map((item) => (
          <li key={item.id}>{item.label}</li>
        ))}
      </ul>
    </main>
  );
}

const rootRoute = createRootRoute({ component: () => <Outlet /> });
const indexRoute = createRoute({ getParentRoute: () => rootRoute, path: "/", component: Widget });
const routeTree = rootRoute.addChildren([indexRoute]);

export const router = createRouter({ routeTree, basepath });

