import { Hono } from "hono";

interface Env {
  db: {
    execute: (sql: string, params?: unknown[]) => { rows: Record<string, unknown>[]; columns: string[]; rowsAffected: number };
    batch: (stmts: { sql: string; params?: unknown[] }[]) => unknown[];
  };
}

type AppUser = { id?: string; name?: string; email?: string };

function currentUser(request: Request): AppUser | null {
  const raw = request.headers.get("x-app-user");
  if (!raw) return null;
  try { return JSON.parse(raw) as AppUser; } catch { return null; }
}

function clean(value: unknown, max: number) {
  return String(value ?? "").trim().replace(/[\u0000-\u001f\u007f]/g, "").slice(0, max);
}

const app = new Hono<{ Bindings: Env }>();

app.get("/api/entries", (c) => {
  const { rows } = c.env.db.execute(
    "SELECT id, name, message, created_at FROM entries ORDER BY created_at DESC, id DESC LIMIT 200",
  );
  return c.json({ entries: rows });
});

app.post("/api/entries", async (c) => {
  let body: { name?: unknown; message?: unknown };
  try { body = await c.req.json(); } catch { return c.json({ error: "Invalid request." }, 400); }
  const user = currentUser(c.req.raw);
  const name = clean(body.name || user?.name, 60);
  const message = clean(body.message, 500);
  if (!name || !message) return c.json({ error: "Name and message are required." }, 400);

  const createdAt = Date.now();
  const result = c.env.db.execute(
    "INSERT INTO entries (name, message, created_at, user_id) VALUES (?, ?, ?, ?)",
    [name, message, createdAt, user?.id ?? null],
  );
  return c.json({ entry: { id: Number(result.rows[0]?.id ?? 0), name, message, created_at: createdAt } }, 201);
});

app.post("/api/tools/count_entries", (c) => {
  const { rows } = c.env.db.execute("SELECT COUNT(*) AS count FROM entries");
  return c.json({ count: Number(rows[0]?.count ?? 0) });
});

export default {
  fetch: (request: Request, env: Env) => app.fetch(request, env),
};

CREATE TABLE IF NOT EXISTS entries (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 60),
  message TEXT NOT NULL CHECK(length(message) BETWEEN 1 AND 500),
  created_at INTEGER NOT NULL,
  user_id TEXT
);

CREATE INDEX IF NOT EXISTS entries_created_at_idx ON entries(created_at DESC);

