import React, { useState } from "react";
import { createRootRoute, createRoute, createRouter, Outlet } from "@tanstack/react-router";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import "./styles.css";

export const basepath = window.location.pathname.endsWith("/")
  ? window.location.pathname
  : window.location.pathname.replace(/\/[^/]*$/, "/");

type Entry = { id: number; name: string; message: string; created_at: number };

function initials(name: string) {
  return name.split(/\s+/).slice(0, 2).map((part) => part[0]).join("").toUpperCase();
}

function Guestbook() {
  const queryClient = useQueryClient();
  const [error, setError] = useState("");
  const entries = useQuery({
    queryKey: ["entries"],
    queryFn: async (): Promise<Entry[]> => {
      const response = await fetch("api/entries");
      if (!response.ok) throw new Error("Could not load the guestbook.");
      return (await response.json()).entries ?? [];
    },
  });
  const addEntry = useMutation({
    mutationFn: async (input: { name: string; message: string }) => {
      const response = await fetch("api/entries", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify(input),
      });
      const body = await response.json();
      if (!response.ok) throw new Error(body.error || "Could not add your entry.");
    },
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ["entries"] }),
  });

  return <main>
    <header className="hero">
      <div className="eyebrow"><span>✦</span> A place for kind words</div>
      <h1>Leave your mark.</h1>
      <p>Sign the guestbook, share a thought, and see who else stopped by.</p>
    </header>

    <section className="layout">
      <aside className="card form-card">
        <div className="card-title"><span className="icon">✎</span><div><h2>Sign the guestbook</h2><p>We'd love to hear from you.</p></div></div>
        <form onSubmit={async (event) => {
          event.preventDefault();
          setError("");
          const form = event.currentTarget;
          const data = new FormData(form);
          try {
            await addEntry.mutateAsync({ name: String(data.get("name") || ""), message: String(data.get("message") || "") });
            form.reset();
          } catch (err) { setError(err instanceof Error ? err.message : "Something went wrong."); }
        }}>
          <label>Your name<input name="name" maxLength={60} required placeholder="Jane Smith" /></label>
          <label>Your message<textarea name="message" maxLength={500} required rows={6} placeholder="Share a note, a memory, or simply say hello…" /></label>
          {error && <div className="error">{error}</div>}
          <button disabled={addEntry.isPending}>{addEntry.isPending ? "Signing…" : "Sign the guestbook"}<span>→</span></button>
        </form>
      </aside>

      <section className="entries">
        <div className="entries-heading"><div><h2>Recent notes</h2><p>{entries.data?.length ?? 0} {(entries.data?.length ?? 0) === 1 ? "person has" : "people have"} signed</p></div><span className="live">● LIVE</span></div>
        {entries.isLoading && <div className="empty">Opening the guestbook…</div>}
        {entries.isError && <div className="empty">We couldn't open the guestbook. Please try again.</div>}
        {!entries.isLoading && !entries.data?.length && <div className="empty"><strong>Be the first to sign.</strong><br />Your note will appear right here.</div>}
        <div className="entry-list">
          {entries.data?.map((entry) => <article className="entry-card" key={entry.id}>
            <div className="avatar">{initials(entry.name)}</div>
            <div><div className="entry-meta"><strong>{entry.name}</strong><time>{new Intl.DateTimeFormat(undefined, { dateStyle: "medium" }).format(new Date(entry.created_at))}</time></div><p>{entry.message}</p></div>
          </article>)}
        </div>
      </section>
    </section>
    <footer>Made for good conversations <span>♥</span></footer>
  </main>;
}

const rootRoute = createRootRoute({ component: () => <Outlet /> });
const indexRoute = createRoute({ getParentRoute: () => rootRoute, path: "/", component: Guestbook });
export const router = createRouter({ routeTree: rootRoute.addChildren([indexRoute]), basepath });

